P.entries["quest:8682"] = {n="Skyseer the Elder",s="Skyseer the Elder este un spirit stramosesc venerat, care salasluieste in varful Freewind Post in timpul Lunar Festival. Calatorii il cauta sus, deasupra Thousand Needles, pentru a le aduce omagiu stramosilor si a-i primi binecuvantarea straveche.",h="Skyseer the Elder este un spirit stramosesc venerat, care salasluieste in varful Freewind Post in timpul...",kw={"stramos","monede ale stramosilor","Elder Skyseer","Freewind Post","Lunar Festival","Skyseer","Thousand Needles"},ang={["class:Druid"]="Comuniunea cu spiritele stravechi in lumina lunii se potriveste indeaproape cu invataturile lui Cenarius si cu cinstirea celor care au strabatut tinutul inaintea noastra.",["faction:Alliance"]="Elder Skyseer se odihneste in fortareata Horde din Freewind Post, obligand pelerinii Alliance sa strabata inaltimile primejdioase si sa infrunte garzile ostile pentru a-i aduce omagiu.",["race:Tauren"]="Salutarea unui batran venerat, in varful uneia dintre cele mai emblematice asezari de pe mesa ale poporului tau, intruchipeaza profunda veneratie pe care Shu'halo o poarta neamului lor stramosesc."},sec={{t="Un far in Needles",b="Aflat pe stancile inalte de lemn din Freewind Post, Elder Skyseer pare scaldat intr-un stalp stralucitor de lumina cereasca. Pozitionat langa podurile care duc spre ascensoarele mecanice uriase, prezenta sa fantomatica ofera un sanctuar linistit printre platourile batute de vant din Thousand Needles."},{t="Calea stramosilor",b="Elder Skyseer ii primeste pe aventurierii care vin sa cinsteasca trecutul in timpul sarbatorii Lunar Festival. Pe langa faptul ca le recunoaste omagiul, batranul venerabil ii poate indruma pe calatori spre rudele sale raspandite prin Kalimdor, printre care Elder Morningdew si Elder Runetotem."}},faq={{q="Unde se afla Elder Skyseer?",a="Elder Skyseer se afla pe mesa superioara din Freewind Post, in Thousand Needles, langa podurile suspendate din apropierea lifturilor de pe marginea stancii.",al={"locatia lui skyseer","unde se afla skyseer","elder din Freewind Post"}},{q="Care este scopul cautarii lui Elder Skyseer?",a="In timpul Lunar Festival, calatorii ii viziteaza pe spirite stramosesti precum Elder Skyseer, pentru a le aduce omagiul, a primi un Coin of Ancestry si a afla unde se gasesc alti batrani.",al={"de ce sa-l vizitez pe clarvazator","obiectivul misiunii clarvazatorului","clarvazatorul Lunar Festival"}},{q="De ce straluceste Elder Skyseer?",a="Ca si ceilalti spirite venerate care viziteaza festivalul, Elder Skyseer este luminat din ceruri de o raza stralucitoare de lumina a lunii, care il arata drept un stramos aflat in comuniune cu cei vii.",al={"de ce este Skyseer in lumina","raza de lumina a batranului"}},{q="Pentru ce alti batrani iti da Skyseer indicatii?",a="Elder Skyseer ofera indrumari despre cum pot fi gasite spiritele stramosesti din apropiere, inclusiv Elder Morningdew, Elder Runetotem, Elder Dreamseer si Elder Wildmane.",al={"alti batrani","pe cine mentioneaza skyseer","indicatii de la skyseer"}},{q="Pot calatorii din Alliance sa vorbeasca cu Elder Skyseer?",a="Da, desi Freewind Post este o asezare Horde puternic fortificata. Aventurierii Alliance trebuie sa se fereasca de garzi pentru a se apropia de batran fara sa starneasca varsare de sange.",al={"poate Alliance sa vorbeasca cu Skyseer","elderul Alliance din Freewind Post"}},{q="Ce se intampla cand vorbesti cu Elder Skyseer?",a="Dupa ce il saluti si ii aduci omagiu, Elder Skyseer iti lauda spiritul si iti ofera un simbol al binecuvantarii stramosilor, incheind astfel scurta intalnire.",al={"recompensa Skyseer","finalizarea misiunii Skyseer the Elder"}}},fp="17,236,23.288.0,18.281.0,31.143.0,49.189.0,29.188.0,55.154.0,48.178.0,45.145.0"}
P.entries["quest:869"] = {n="Raptor Thieves"}
P.entries["quest:87"] = {n="Goldtooth",s="In apropiere de Fargodeep Mine, lipseste colierul lui Auntie Bernice Stonefield, iar familiile Stonefield si Maclure se invinuiesc reciproc. Billy Maclure recunoaste ca l-a pierdut in timp ce se juca prin apropiere, iar tu urmezi urma pana la koboldul Goldtooth.",h="In apropiere de Fargodeep Mine, lipseste colierul lui Auntie Bernice Stonefield, iar familiile Stonefield si...",kw={"bernice","billy","fargodeep","goldtooth","kobold","maclure","colier","stonefield"},ang={["race:Human"]="Ca Human, ajuti la aplanarea tensiunilor dintre doua dintre cele mai vechi familii de fermieri din Elwynn si infrunti kobolzii care napadesc regatul."},sec={{t="Pozna unui baiat",b="Disparitia colierului lui Auntie Bernice Stonefield a starnit necazuri intre familiile Stonefield si Maclure. Bernice isi banuieste rivalii, dar Billy Maclure a pierdut bijuteria in timp ce se juca langa Fargodeep Mine. Incearca sa-si ascunda vinovatia, spunand ca doar a gasit colierul, inainte ca o creatura sa i-l smulga."},{t="The Den deasupra minei",b="Billy spune ca un kobold mare, cu colti stralucitori, a luat colierul lucios si a fugit intr-o vizuina deasupra Fargodeep Mine. Goldtooth pandeste, de fapt, la nivelul inferior al minei. Uciderea koboldului readuce colierul lui Bernice, pune capat disputei dintre familii si-ti aduce o veche amintire de campanie lasata de raposatul sot al lui Bernice."}},faq={{q="Cine a furat colierul lui Auntie Bernice?",a="Cel mai probabil, Billy Maclure a luat colierul lui Auntie Bernice. Ii scapa ca l-a pierdut in timp ce se juca in apropiere de Fargodeep Mine, apoi spune ca doar l-a gasit acolo. Inainte sa-l poata recupera, Goldtooth, koboldul, a pus mana pe podoaba stralucitoare.",al={"cine a furat colierul","cine a luat colierul","au furat maclures colierul"}},{q="Unde poate fi gasit Goldtooth?",a="Goldtooth pandeste la nivelul inferior din Fargodeep Mine, desi Billy spune ca vizuina koboldului se afla deasupra minei.",al={"locatia lui Goldtooth","unde este Goldtooth","gaseste-l pe Goldtooth"}},{q="Ce fel de creatura este Goldtooth?",a="Goldtooth este un kobold enorm, cu un colti de aur stralucitor. Ca si ceilalti koboldi, este atras de podoabe luminoase si sclipitoare.",al={"ce este goldtooth","este goldtooth un kobold"}},{q="Ce legatura are aceasta misiune cu disputa dintre Maclure si Stonefield?",a="Stonefields si Maclures sunt rivali inversunati, care se acuza reciproc de furturi marunte si nenorociri. Auntie Bernice banuieste ca Maclures i-au luat colierul din ciuda, dar cautarile dezvaluie ca Billy l-a pierdut din neglijenta.",al={"drama dintre Stonefield si Maclure","de ce o invinuieste Bernice pe Billy"}},{q="Care este recompensa oferita de Auntie Bernice?",a="Auntie Bernice iti da un vechi suvenir care i-a apartinut raposatului ei sot. Spune ca purta noroc, dar el a uitat sa-l ia in ultima sa campanie militara.",al={"recompensa Bernice","ce primesti"}},{q="Ce misiune duce direct la Goldtooth?",a="Back to Billy duce direct la Goldtooth. Il mituiesti pe Billy Maclure cu carne de porc, iar el marturiseste in cele din urma ce s-a intamplat cu colierul.",al={"conditie prealabila pentru goldtooth","misiune dinaintea lui goldtooth"}}},fx={["36c74007"]={q="De ce vrea Billy Maclure sa-si recupereze colierul lui Bernice?",a="Billy a scapat din greseala colierul lui Auntie Bernice in timp ce se juca langa Fargodeep Mine, desi e disperat sa nege ca l-ar fi furat. Stie ca va avea mari necazuri daca ramane pierdut, mai ales din cauza vrajbei aprige dintre Maclures si Stonefields. Daca il recuperezi din mainile koboldului, il ajuti sa indrepte lucrurile fara sa dea direct piept cu mania lui Bernice.",al={"motivul lui Billy Maclure","de ce vrea Billy colierul","de ce sa-l ajuti pe Billy Maclure"}},b7400482={q="Ce este Bernice's Necklace?",a="Bernice's Necklace este o mostenire de familie pretuita, care ii apartine lui \"Auntie\" Bernice Stonefield. Dupa ce a disparut in toiul rivalitatii acerbe dintre familiile Stonefield si Maclure, a ajuns pe mana unui kobold lacom. Pentru Bernice, valoarea ei este in mare parte sentimentala, iar ea isi doreste cu disperare sa o recupereze la Stonefield Farm.",al={"colierul lui Bernice","ce este colierul lui Auntie Bernice","la ce foloseste colierul lui Bernice"}},["4539d353"]={q="De ce te roaga Billy pe tine, si nu pe garzi?",a="Billy este doar un copil speriat, care isi ascunde vinovatia, iar daca ar chema garzile din Stormwind, s-ar afla ca el a luat sau a manuit gresit bijuteriile lui Bernice Stonefield. In plus, garzile locale sunt deja coplesite de lupta impotriva banditilor Defias si a gnolilor din Elwynn Forest, asa ca e putin probabil sa vaneze un kobold agresiv din pricina colierului pierdut al unei batrane.",al={"de ce eu, billy","de ce nu gardienii din stormwind","de ce are billy nevoie de ajutor"}}},fp="9,231,16.309.0,22.313.0,36.232.1,29.111.0,35.120.0,61.229.1,39.155.0,41.135.0"}
