P.entries["quest:88756"] = {n="Bring Back a Bang",s="Bring Back a Bang este o misiune de recuperare a prafului exploziv volatil furat de pe un santier local. Piticii ostili Dark Iron au dus butoaiele marcate spre est, in taberele lor de pe Direforge Hill; daca nu sunt opriti, reprezinta o amenintare grava pentru zona.",h="Bring Back a Bang este o misiune de recuperare a prafului exploziv volatil furat de pe un santier local.",kw={"pulbere exploziva","bring back a bang","santier","dark iron dwarf","direforge hill","explozibili furati"},ang={["profession:Engineering"]="Inginerii stiu ca pulberea exploziva si compusii volatili cer respect si izolare corespunzatoare, iar depozitele nesupravegheate sunt o nenorocire gata sa se produca.",["race:Dwarf"]="Constructorii si excavatorii pitici inteleg prea bine potentialul distructiv al explozibililor minieri, mai ales daca acestia ajung in mainile rudelor lor dusmane, Dark Iron."},sec={{t="Furtul de pe santier",b="Piticii ostili Dark Iron si-au stabilit tabere la est, pe Direforge Hill. Profitand de lucrarile de constructie din apropiere, au jefuit un santier local, au furat pulbere exploziva esentiala si au dus stocurile inapoi la corturile lor."},{t="Maini instabile",b="Praful exploziv aflat in mainile unor Dark Iron rauvoitori reprezinta un pericol iminent pentru tinuturile din jur. Butoaiele furate poarta insemne rosii clare, care le deosebesc de proviziile obisnuite, iar recuperarea lor inainte ca Dark Iron sa le foloseasca in scopuri distructive este o prioritate urgenta."}},faq={{q="Cine a furat explozibilii?",a="Pitici Dark Iron au jefuit un santier din apropiere si au dus butoaie cu pulbere exploziva la corturile lor, la est, pe Direforge Hill.",al={"cine a furat explozibilii","cine a luat butoaiele","pulbere furata"}},{q="Unde au dus Dark Irons butoaiele?",a="Butoaiele cu praf de pusca furat au fost duse spre est, la taberele Dark Iron dwarf din toata zona Direforge Hill.",al={"unde sunt explozibilii","taberele de pe Direforge Hill","unde este praful furat"}},{q="Cum poti identifica explozibilii furati?",a="Explozibilii de constructie furati se deosebesc de butoaiele obisnuite prin marcajele rosii distinctive pictate pe ele.",al={"cum arata butoaiele","cum identifici praful de pusca","butoaie marcate cu rosu"}},{q="De ce trebuie recuperati explozibilii?",a="Muncitorii din constructii nu-si pot permite sa renunte la materiale, iar lasarea unei pulberi explozive puternice in mainile piticilor Dark Iron rauvoitori reprezinta o amenintare serioasa pentru toti cei din apropiere.",al={"de ce sa recuperez praful","care este amenintarea Dark Iron","de ce sa-i oprim pe Dark Iron"}},{q="Ce este Direforge Hill?",a="Direforge Hill se afla la est de santierul local si a ajuns infestat de tabere ostile Dark Iron dwarf.",al={"ce este direforge hill","povestea dealului direforge"}},{q="Cine sunt piticii Dark Iron?",a="Piticii Dark Iron sunt o factiune tradatoare, vestita pentru rautatea, vrajitoria intunecata si ostilitatea neincetata fata de rudele si vecinii lor.",al={"cine sunt piticii Dark Iron","de ce sunt Dark Iron ostili"}}},fp="17,251,30.268.0,14.286.0,25.132.0,42.106.0,43.125.0,43.161.0,23.119.0,30.151.0"}
P.entries["quest:888"] = {n="Stolen Booty"}
