P.entries["quest:89"] = {n="The Everstill Bridge",s="Everstill Bridge este un proiect de reconstructie condus de Foreman Oslow in Lakeshire, menit sa repare podul de piatra avariat al orasului. Lucrarile s-au oprit, deoarece fierul destinat proiectului a fost transformat in arme in timpul ultimei invazii a orcilor, iar caravana de inlocuire venita din Stormwind a fost atacata in ambuscada de gnolii din Redridge.",h="Everstill Bridge este un proiect de reconstructie condus de Foreman Oslow in Lakeshire, menit sa repare podul...",kw={"everstill bridge","foreman oslow","sulite de fier","nituri de fier","lakeshire","redridge","gnolii din redridge"},ang={["faction:Alliance"]="Intreruperea lanturilor de aprovizionare din Lakeshire este un alt semn izbitor al neglijentei Stormwind fata de teritoriile de la marginea regatului, care-i obliga pe sefii locali sa angajeze mercenari pentru a proteja comertul rutier.",["profession:Blacksmithing"]="Lipsa proviziilor arata cat de disperati erau aparatorii din Lakeshire: confectionarea armelor din pari de sustinere si nituri a fost o masura de ultima instanta, care a salvat vieti cu pretul unei infrastructuri vitale."},sec={{t="Un oras izolat",b="Podul de piatra care traverseaza Lake Everstill este vital pentru Lakeshire, legand drumurile vestice ce duc inapoi spre Elwynn Forest de malul indepartat si de trecatorile nordice. In timpul recentelor incursiuni ale orcilor, orasul a fost impins in pragul dezastrului. Cu supravietuirea in cumpana, Lakeshire si-a topit rezervele de fier structural pentru a fauri munitii, lame si armuri de placi cu care sa-i respinga pe invadatorii Blackrock, lasand podul neterminat si vulnerabil."},{t="Transporturi furate",b="Foreman Oslow a cerut House of Nobles si Stormwind materiale de constructie noi pentru a incheia reparatiile. A fost trimisa o caravana cu provizii incarcata cu fier, dar nu a ajuns niciodata la destinatie. O banda de gnolli din Redridge a atacat convoiul pe drum, ducand in taberele lor din dealurile nordice tarusi si nituri esentiale din fier. Fara calatori aventurosi dispusi sa recupereze materialele furate, proiectul podului ramane in impas, in timp ce gnolii si orcii isi strang stapanirea asupra muntilor."}},faq={{q="De ce nu a fost terminat Everstill Bridge?",a="Lakeshire a fost nevoita sa topeasca fierul destinat constructiilor pentru a-l transforma in arme, gloante si armuri, ca sa supravietuiasca invaziei recente a orcilor. Ulterior, un transport de inlocuire trimis din Stormwind a fost prins intr-o ambuscada si jefuit de gnollii din zona, lasandu-l pe Foreman Oslow fara materialele necesare pentru a termina lucrarea.",al={"de ce este rupt podul","cine a rupt Everstill Bridge","podul din Lakeshire este rupt"}},{q="Cine este Foreman Oslow?",a="Foreman Oslow este mesterul constructor care supravegheaza reconstructia podului de peste Lake Everstill. Izolat si lipsit de sprijin ori materiale din capitala, se bazeaza pe aventurierii aflati in trecere pentru a recupera din dealuri materialele de constructie furate.",al={"foreman oslow","cine este oslow"}},{q="Cine a furat proviziile pentru pod?",a="Gnollii din Redridge au atacat prin surprindere caravana de aprovizionare venita din Stormwind si au dus tarusii de fier si niturile in taberele lor din dealurile din spatele Lakeshire.",al={"cine a furat niturile de fier","cine a luat fierul podului"}},{q="De ce nu a trimis Stormwind garzi sa protejeze caravana?",a="In lipsa regelui Varian Wrynn, House of Nobles din Stormwind a refuzat in mare masura sa trimita ajutor militar teritoriilor indepartate. Redridge Mountains a fost lasat sa se descurce singur impotriva gnollilor si orcilor Blackrock, cu sprijin minim din partea garzilor oraselor.",al={"ajutor stormwind lakeshire","de ce nu sunt garzi"}},{q="De ce a topit Lakeshire fierul?",a="In timpul ultimei invazii a orcilor, aparatorii din Lakeshire au ramas periculos de putin aprovizionati cu materiale de razboi. Pentru a supravietui asaltului, orasul si-a topit rezervele de fier pentru constructii si le-a transformat in armuri, sabii si munitie.",al={"de ce sa topim fierul","invazia orcilor in Redridge"}},{q="Ce provizii sunt necesare pentru a repara podul?",a="Foreman Oslow are nevoie in mod special de tarusi grei de fier si nituri de fier pentru a consolida si fixa bine tronsoanele podului de peste Lake Everstill.",al={"materiale pentru pod","de ce are nevoie Oslow"}}},fx={f119d943={q="De ce are nevoie Foreman Oslow de reconstruirea podului Everstill Bridge?",a="Foreman Oslow are sarcina de a restabili legatura vitala dintre Lakeshire si celalalt mal al Lake Everstill. Podul leaga orasul de drumurile din jur si de sudul Redridge, insa razboaiele din trecut au obligat locuitorii sa topeasca fierul structurii pentru a face arme si armuri. Fara materiale pentru pod, orasul ramane vulnerabil, izolat si incapabil sa asigure circulatia sau apararea obisnuite.",al={"motivul lui Foreman Oslow","de ce sa reconstruim podul","de ce ii pasa lui Oslow"}},f9ba0cdb={q="La ce folosesc Iron Pikes si Iron Rivets?",a="Tarusii si niturile de fier sunt elemente structurale menite sa intareasca si sa sprijine schelele de lemn si podurile de piatra ale Everstill Bridge. Au fost trimise initial din Stormwind, inainte ca gnolii din Redridge sa jefuiasca trasura cu provizii, lasand echipa lui Oslow complet blocata, fara elemente de fixare metalice.",al={"la ce folosesc tarusii de fier","la ce folosesc niturile de fier","de ce are Oslow nevoie de tarusi si nituri"}},["9c1de71f"]={q="De ce au gnolii din Redridge materialele pentru pod?",a="O banda de gnolli din Redridge aflata la prada a atacat si jefuit caravana care venea din Stormwind, ducand sulitele si nituri de fier in dealurile de la nord de Lakeshire. Gnollii jefuiesc oportunist proviziile de pe drumuri, profitand de izolarea orasului Lakeshire si de lipsa protectiei militare.",al={"cine a furat niturile","de ce au gnolii fier","tinta gnolilor din Redridge"}},ecd0e353={q="De ce ti-o cere Foreman Oslow tie si nu garzii orasului?",a="Garnizoana locala din Lakeshire este solicitata la maximum pentru a apara perimetrul orasului de orcii Blackrock invadatori si de haitele de gnolli agresivi. Cum Stormwind nu trimite aproape niciun intaritor militar, garzile orasului nu pot trimite oameni sa scotoceasca dealurile dupa materiale de constructie furate, asa ca Oslow trebuie sa se bazeze pe aventurierii aflati in trecere.",al={"de ce nu garzile din Lakeshire","de ce eu la Everstill Bridge","de ce nu ia garda proviziile"}}},fp="20,319,14.449.0,16.491.0,39.292.0,21.244.0,30.165.0,56.254.0,39.212.0,46.137.0"}
