P.entries["quest:8921"] = {n="The Ectoplasmic Distiller",s="Mux Manascrambler din Gadgetzan lucreaza la dispozitivul sau extradimensional de dezvaluire a fantomelor, dar a ramas fara fonduri si personal. Prima piesa de care are nevoie este un Ectoplasmic Distiller, iar el iti cere o lista de materiale costisitoare si patruzeci de gold pentru a-l construi.",h="Mux Manascrambler din Gadgetzan lucreaza la dispozitivul sau extradimensional de dezvaluire a fantomelor, dar...",kw={"convertor arcanite","burning steppes","ectoplasmic distiller","gadgetzan","mux manascrambler","ulei stonescale","tanaris","cenusa vulcanica"},sec={{t="De ce are nevoie Mux",b="Dupa A Supernatural Device, Mux Manascrambler iti primeste ajutorul pentru dezvaluitorul sau de fantome, o masinarie menita sa ajunga dincolo de dimensiuni. Prima piesa este un distilator, menit sa adune insasi tesatura mortii, iar el te avertizeaza ca nu va fi usor sa-l construiasca. Are nevoie de un convertor delicat de arcanita, patru esente eterne superioare, zece unitati de ulei de solzi de piatra si douazeci si cinci de unitati de cenusa vulcanica, plus patruzeci de piese de aur. Cenusa este pentru un filtru si trebuie sa provina din bazinele de lava din Burning Steppes. Mux recunoaste ca materialele sunt scumpe, dar jura ca va fi nevoie de fiecare dintre ele."},{t="Multumirile lui Mux",b="Mux spune ca acestea sunt exact materialele de care avea nevoie si ca ai ajuns la momentul potrivit. Promite sa-ti pregateasca distilatorul in cateva clipe si iti da ceva drept rasplata pentru osteneala."}},faq={{q="Cine cere aceste materiale?",a="Mux Manascrambler din Gadgetzan, in Tanaris, care construieste un dispozitiv de detectare a fantomelor din alta dimensiune.",al={"cel care da misiunea","cine ofera misiunea","cine este mux"}},{q="De ce materiale are nevoie Mux?",a="Un convertor de arcanit delicat, patru esente eterne superioare, zece uleiuri de solz de piatra, douazeci si cinci de cenusa vulcanica si patruzeci de aur.",al={"obiecte necesare","de ce am nevoie","materiale pentru distilator"}},{q="Unde se gaseste cenusa vulcanica?",a="Mux spune sa-l aduni din bazinele de lava din Burning Steppes.",al={"locatia cenusii vulcanice","de unde sa iei cenusa"}},{q="De ce are Mux nevoie de aceste componente specifice?",a="Acestea ajung intr-un Ectoplasmic Distiller, un dispozitiv pentru colectarea substantei din care e alcatuita moartea. Cenusa vulcanica serveste la construirea filtrului acestuia.",al={"de ce arcanite","la ce foloseste cenusa","de ce aceste obiecte"}},{q="Ce urmeaza dupa livrarea materialelor?",a="Hunting for Ectoplasm este pasul urmator.",al={"pasul urmator","ce se intampla mai departe","misiunea urmatoare"}}},fp="25,249,14.555.0,12.186.1,29.96.0,32.124.0,32.63.0,44.130.0,42.39.0"}
P.entries["quest:8922"] = {n="A Supernatural Device",s="Deliana cauta o cale de a vorbi cu fantoma lui Anthion Harmon. Un inginer cu o fascinatie aparte pentru supranatural spune ca poate construi o masina care sa vorbeasca cu mortii, iar tu ii duci sangele pe care l-ai strans, in Gadgetzan, drept plata.",h="Deliana cauta o cale de a vorbi cu fantoma lui Anthion Harmon.",kw={"anthion harmon","deliana","gadgetzan","mux manascrambler","recipient de venin sigilat","dispozitiv supranatural","tanaris"},ang={["faction:Alliance"]="Deliana trimite aventurierii Alliance la Mux Manascrambler din Gadgetzan."},sec={{t="Plata pentru un inginer",b="Deliana cauta o cale de a ajunge la Anthion Harmon sau, mai exact, la fantoma lui. Inginerul la care se gandeste Deliana este Mux Manascrambler, care se lauda ca are o masinarie cu care poti vorbi cu mortii. Sangele tau era destinat lui de la bun inceput, asa ca du-l la Gadgetzan, in Tanaris, si da-i-l lui Mux in schimbul serviciilor sale."},{t="O livrare binevenita",b="Mux se bucura sa primeasca sangele, fiindca era pe terminate. Apoi te intreaba daca Deliana te-a trimis."}},faq={{q="De ce te trimite Deliana la Gadgetzan?",a="Deliana vrea sa vorbeasca cu fantoma lui Anthion Harmon. Un inginer din Gadgetzan sustine ca poate construi o masinarie cu care sa vorbeasca cu mortii, asa ca ii duci plata.",al={"de ce sa mergi la Gadgetzan","Deliana in Gadgetzan","scopul dispozitivului supranatural"}},{q="Ce se afla in recipientul care este livrat?",a="Este un recipient sigilat cu sangele pe care l-ai adunat, destinat drept plata pentru serviciile inginerului.",al={"ce se afla in recipient","recipient de venin sigilat","al cui sange este acesta"}},{q="Cine primeste livrarea in Gadgetzan?",a="Mux Manascrambler, inginerul din Gadgetzan cu o fascinatie aparte pentru supranatural.",al={"cine primeste recipientul","contactul din Gadgetzan","cine este Mux Manascrambler"}},{q="Ce urmeaza dupa aceasta livrare?",a="Urmeaza Ectoplasmic Distiller.",al={"ce se intampla in continuare","urmatoarea misiune","dupa A Supernatural Device"}}},fp="21,258,23.330.0,18.105.1,39.165.0,45.101.0,39.94.0,27.34.0"}
P.entries["quest:8923"] = {n="A Supernatural Device",s="Mokvar are o intrebuintare pentru mostrele de venin pe care le-ai adunat: sunt pentru un cunoscut, Mux Manascrambler, aflat in Gadgetzan. Mux lucreaza la un dispozitiv care sa permita vorbirea cu mortii, iar Mokvar spera ca acesta il va ajuta sa ia legatura cu Anthion.",h="Mokvar are o intrebuintare pentru mostrele de venin pe care le-ai adunat: sunt pentru un cunoscut, Mux...",kw={"anthion","gadgetzan","mokvar","mux manascrambler","recipient sigilat cu venin","dispozitiv supranatural","tanaris"},ang={["faction:Horde"]="Mokvar trimite aventurierii Horde la Mux Manascrambler in Gadgetzan."},sec={{t="Venin pentru un inginer",b="Mokvar remarca faptul ca trebuie sa fii curajos ca ai ramas si spune ca mai este de obtinut armura pentru oricine este inca dispus sa ajute. Veninul pe care l-ai adunat ii apartine unei cunostinte, Mux Manascrambler, un inginer interesat de supranatural. Proiectul actual al lui Mux este un dispozitiv pentru a vorbi cu mortii. Mokvar isi pune ultima speranta in el: sa ia legatura cu Anthion si sa afle mai multe despre propria situatie. Du recipientul sigilat la Mux, in Gadgetzan, in Tanaris."},{t="O livrare binevenita",b="Mux se bucura sa primeasca veninul, fiindca proviziile erau pe terminate. Apoi Mux te intreaba daca Mokvar te-a trimis."}},faq={{q="Cine te trimite in aceasta cursa de livrare?",a="Mokvar, care vrea ca recipientul sigilat cu venin sa fie dus unei cunostinte din Gadgetzan.",al={"cine da aceasta misiune","cel care da misiunea","mokvar"}},{q="Unde trebuie dusa otrava?",a="Lui Mux Manascrambler, in Gadgetzan, in Tanaris.",al={"unde duc veninul","locatia de predare","locatia lui mux"}},{q="Cine este Mux Manascrambler?",a="Un inginer fascinat de supranatural si cunoscut al lui Mokvar.",al={"cine este mux","povestea lui mux manascrambler"}},{q="Ce construieste Mux?",a="Un dispozitiv care iti permite sa comunici cu mortii. Este cel mai recent proiect al lui Mux.",al={"ce este dispozitivul","ce construieste mux","dispozitiv supranatural"}},{q="De ce vrea Mokvar sa ajunga la morti?",a="Mokvar spera sa ajunga la Anthion si sa afle mai multe despre propria situatie, iar dispozitivul i se pare ultima sansa.",al={"de ce sa-l contactezi pe anthion","cine este anthion","motivul lui mokvar"}}},fp="21,223,21.470.0,18.106.1,36.83.0,32.46.0,25.76.0,21.77.0,39.113.0"}
P.entries["quest:8924"] = {n="Hunting for Ectoplasm",s="Mux Manascrambler din Gadgetzan si-a pregatit distilatorul ectoplasmatic si acum are nevoie de ectoplasma. O vei duce in trei tinuturi indepartate, Silithus, Winterspring si Eastern Plaguelands, si vei aduna cate douasprezece din fiecare fel de la mortii fara trup. Aceasta misiune urmeaza dupa The Ectoplasmic Distiller.",h="Mux Manascrambler din Gadgetzan si-a pregatit distilatorul ectoplasmatic si acum are nevoie de ectoplasma.",kw={"eastern plaguelands","ectoplasmic distiller","frozen ectoplasm","gadgetzan","hunting for ectoplasm","mux manascrambler","scorched ectoplasm","silithus","stable ectoplasm","winterspring"},sec={{t="Trei climate, trei feluri",b="Mux Manascrambler este mandru de aparatul de distilare si te avertizeaza ca ai de calatorit mult pentru a gasi mortii-vii fara trup. In viziunea lui Mux, clima schimba felul in care este alcatuita tesatura spectrala a mortilor. Silithus a chinuit night elves, Winterspring are spiritele celor din neamul Highborne, iar Eastern Plaguelands adaposteste fantome si banshee. Fiecare loc ofera ectoplasma diferita: douasprezece arse, douasprezece inghetate si douasprezece stabile. Mux spune sa asezi aparatul de distilare in apropiere inainte de recoltare, apoi sa-l aduci inapoi la Gadgetzan impreuna cu ectoplasma."},{t="Verdictul lui Mux",b="Mux este incantat de ectoplasma. Mux explica faptul ca energiile din alte lumi aflate in ea iti vor permite sa iei legatura cu sufletele care nu au parasit pe deplin aceasta lume."}},faq={{q="Cine te trimite sa aduni ectoplasma?",a="Mux Manascrambler din Gadgetzan, in Tanaris, dupa ce distilatorul lui este construit.",al={"cine ofera Hunting for Ectoplasm","cel care da misiunea Hunting for Ectoplasm"}},{q="De ce are Mux nevoie de ectoplasma din trei locuri diferite?",a="Mux spune ca climatele diferite dau tesaturii spectrale a mortilor consistente diferite. Vrea douasprezece bucati parjolite din Silithus, douasprezece inghetate din Winterspring si douasprezece stabile din Eastern Plaguelands.",al={"de ce trei ectoplasme","tipuri diferite de ectoplasma","de ce silithus winterspring plaguelands"}},{q="Ce spirite furnizeaza ectoplasma?",a="Night Elves torturati in Silithus, spirite ale highborne in Winterspring si fantome si banshee in Eastern Plaguelands.",al={"ce inamici lasa ectoplasma","ce trebuie sa omor pentru ectoplasma","ce fantome o lasa"}},{q="Cum se aduna ectoplasma?",a="Mux spune sa asezi distilatorul langa mortii-vii fara trup inainte sa-i recoltezi.",al={"cum functioneaza distilatorul","cum colectez ectoplasma"}},{q="Cum se incadreaza aceasta in munca lui Mux?",a="Urmeaza dupa The Ectoplasmic Distiller, iar A Portable Power Source vine dupa aceasta.",al={"cerinte pentru Hunting for Ectoplasm","ce misiune se face inainte de Hunting for Ectoplasm"}}},fp="21,278,27.533.0,13.155.1,34.72.0,56.209.0,36.127.0,30.87.0,34.81.0"}
P.entries["quest:8925"] = {n="A Portable Power Source",s="Cu ectoplasma in mana, Mux Manascrambler are nevoie de o sursa de energie stabila si portabila, care sa o mentina activa. A auzit zvonuri despre Magma Lord Bokk, un elementar din Burning Steppes, a carui inima este un Magma Core, si vrea sa i-l aduci la Gadgetzan.",h="Cu ectoplasma in mana, Mux Manascrambler are nevoie de o sursa de energie stabila si portabila, care sa o...",kw={"blackrock mountain","burning steppes","gadgetzan","dezvaluitor de fantome","magma core","magma lord bokk","mux manascrambler"},sec={{t="O inima de foc nesfarsit",b="Dupa Hunting for Ectoplasm, Mux Manascrambler vrea o sursa de energie constanta si mobila, care sa mentina ectoplasma activa. Se zvoneste ca Magma Lord Bokk, un elemental puternic, poarta un Magma Core in loc de inima, o sursa nesfarsita de caldura. Se spune ca Magma Lord locuieste in Burning Steppes, la sud de Blackrock Mountain si la vest de Pillar of Ash. Mux vrea sa-i duci nucleul la Gadgetzan, ca detectorul de fantome extradimensionale sa poata functiona."},{t="In sfarsit, putere",b="Mux este incantat cand sosesti cu nucleul si declara ca acesta ii va oferi cu siguranta dezvaluitorului de fantome toata energia necesara."}},faq={{q="De ce are nevoie Mux Manascrambler de o sursa de energie?",a="Mux vrea o sursa de energie constanta si portabila, suficienta pentru a mentine ectoplasma in miscare si pentru a alimenta dispozitivul de detectare a fantomelor extradimensionale.",al={"de ce ai nevoie de o sursa de energie","la ce foloseste sursa de energie","de ce nucleu de magma"}},{q="Cine este Magma Lord Bokk?",a="Un elemental puternic, spun zvonurile, cu un Magma Core in loc de inima, o sursa de caldura care nu seaca niciodata.",al={"cine este bokk","legende despre Magma Lord Bokk","unde se afla bokk"}},{q="Unde poate fi gasit Magma Lord Bokk in Burning Steppes?",a="Zvonurile il plaseaza in Burning Steppes, la sud de Blackrock Mountain si la vest de Pillar of Ash.",al={"locatia lui bokk","unde se afla magma lord bokk","gaseste-l pe magma lord bokk"}},{q="Unde se incadreaza acest pas in munca lui Mux?",a="Urmeaza dupa Hunting for Ectoplasm, iar apoi vine A Shifty Merchant.",al={"ce urmeaza inainte","ordinea lantului de misiuni","ce urmeaza"}}},fp="23,261,23.446.0,13.131.1,47.126.0,23.107.0,58.107.0,41.71.0"}
P.entries["quest:8928"] = {n="A Shifty Merchant",s="Mux Manascrambler are nucleul necesar pentru a-si alimenta dispozitivul, iar acum are nevoie de o tija care sa poata transporta acea energie fara sa se topeasca. A intalnit candva un imp in Winterspring care vindea marfuri exotice si regreta ca nu a cumparat tija elementala oferita. Il cauti pe imp intr-o pestera de la intrarea in Darkwhisper Gorge si cumperi Fel Elemental Rod.",h="Mux Manascrambler are nucleul necesar pentru a-si alimenta dispozitivul, iar acum are nevoie de o tija care...",kw={"darkwhisper gorge","bagheta elementala fel","gadgetzan","imp","negustor","mux manascrambler","winterspring"},sec={{t="Impul din pestera",b="Dupa A Portable Power Source, Mux Manascrambler trece la urmatoarea problema: o tija care sa poata purta puterea miezului fara sa se topeasca. Mux a intalnit un imp in Winterspring care vindea tot felul de marfuri exotice, iar tija elementala a impului ar fi fost perfecta. Mux se invinovateste ca n-a cumparat-o. Impul locuieste intr-o pestera de la intrarea in Darkwhisper Gorge, in sudul Winterspring. Gaseste-l, cumpara Fel Elemental Rod si du-l inapoi la Mux, in Gadgetzan. Mux insista ca impul sa-ti ceara doar patruzeci de monede de aur, pretul pe care i-l spusese lui Mux."},{t="Sosirea toiagului",b="Mux este incantat de toiag si spune ca este perfect. Apoi se apuca sa asambleze totul."}},faq={{q="Cine te trimite dupa toiag?",a="Mux Manascrambler se afla in Gadgetzan, in Tanaris.",al={"cine da A Shifty Merchant","cel care da misiunea A Shifty Merchant"}},{q="Ce a fost inainte de acest pas?",a="Urmeaza dupa A Portable Power Source.",al={"misiunea anterioara","conditie prealabila a shifty merchant"}},{q="Unde poate fi gasit negustorul imp?",a="Intr-o pestera de la intrarea in Darkwhisper Gorge, in sudul Winterspring.",al={"unde este imp-ul","locatia imp-ului din Darkwhisper Gorge","unde este negustorul din Winterspring"}},{q="Ce obiect trebuie sa cumperi?",a="O bagheta de elemental fel.",al={"ce obiect sa cumpar","ce vinde imp-ul"}},{q="Cat costa toiagul?",a="Impul i-a cerut lui Mux patruzeci de monede de aur, iar Mux vrea sa nu ti se ceara mai mult.",al={"costul toiagului","cati bani costa toiagul","pretul impului"}},{q="De ce are Mux nevoie de acest toiag?",a="Nucleul va furniza dispozitivului suficienta energie, dar Mux are inca nevoie de o tija capabila sa o suporte fara sa se topeasca.",al={"de ce tija elementala fel","la ce foloseste tija"}}},fp="17,321,19.537.0,15.101.1,28.43.0,27.35.0,36.77.0,35.20.0,27.78.0,27.111.0"}
